// data/pobdata.js (generated by tools/gen_pobdata.lua) against Path of Building v2.67.2's own files at the pin, read
// here as text from PoE-Sim's pinned checkout (../PoE-Sim/sources/pob, SETUP.md there). Tolerance: exact.
"use strict";
const test = require("node:test");
const assert = require("node:assert/strict");
const fs = require("fs");
const path = require("path");
const data = require("../data/pobdata.js");

const pob = process.env.POB_SRC || path.join(__dirname, "..", "..", "PoE-Sim", "sources", "pob", "src");
const read = (f) => fs.readFileSync(path.join(pob, f), "utf8");

test("PoB checkout is the pinned one", () => {
  assert.ok(fs.existsSync(path.join(pob, "GameVersions.lua")), "PoB v2.67.2 checkout expected at " + pob + " (set POB_SRC)");
  assert.equal(data.pob, "v2.67.2 (b32759a)");
  assert.match(read("../changelog.txt"), /^VERSION\[2\.67\.2\]/);
});

test("tree versions: GameVersions.lua treeVersionList, in order, with PoB's display names", () => {
  const src = read("GameVersions.lua");
  const list = /treeVersionList = \{([^}]*)\}/.exec(src)[1].match(/"([^"]+)"/g).map((s) => s.slice(1, -1));
  assert.deepEqual(data.treeOrder, list);
  assert.equal(data.latestTree, list[list.length - 1]);
  for (const v of list) {
    const display = new RegExp('\\["' + v + '"\\] = \\{\\s*display = "([^"]+)"').exec(src);
    assert.equal(data.trees[v].display, display[1], v);
  }
});

test("keystones per tree: the nodes marked isKeystone in TreeData/<v>/tree.lua", () => {
  for (const v of ["3_29", "3_25", "3_10", "2_6"]) {
    const src = read("TreeData/" + v + "/tree.lua");
    const count = (src.match(/\["isKeystone"\]= true/g) || []).length;
    assert.equal(Object.keys(data.trees[v].keystones).length, count, v);
  }
  assert.equal(data.trees["3_29"].keystones["11455"], "Chaos Inoculation");
});

test("item keystone names: Data.lua data.keystones plus the cluster jewel keystones", () => {
  const list = /data\.keystones = \{([^}]*)\}/.exec(read("Modules/Data.lua"))[1].match(/"([^"]+)"/g).map((s) => s.slice(1, -1));
  const cluster = /keystones = \{([^}]*)\}/.exec(read("Data/ClusterJewels.lua"))[1].match(/"([^"]+)"/g).map((s) => s.slice(1, -1));
  assert.deepEqual(data.itemKeystones, list.concat(cluster).sort());
  assert.deepEqual(data.clusterKeystones, cluster);
});

test("gems and skills", () => {
  const gems = Object.values(data.gems);
  assert.ok(gems.length > 800);
  // Every gem's granted effects exist in the skill table.
  for (const g of gems) for (const e of g.e) assert.ok(data.skills[e], g.n + " -> " + e);
  // Data/Gems.lua: the Vaal Cyclone gem grants VaalCyclone then Cyclone.
  assert.deepEqual(data.gems["Metadata/Items/Gems/SkillGemVaalCyclone"].e, ["VaalCyclone", "Cyclone"]);
  assert.equal(data.skills.SupportMeleePhysicalDamage.sup, 1);
});

test("timeless and cluster jewel tables", () => {
  const t = data.trees["3_29"];
  // Data.lua jewelRadii["3_16"]: Small, Medium, Large, Very Large, Massive are indexes 1 to 5.
  assert.deepEqual([t.radii.Small, t.radii.Medium, t.radii.Large, t.radii["Very Large"], t.radii.Massive], [1, 2, 3, 4, 5]);
  assert.deepEqual([data.trees["3_10"].radii.Small, data.trees["3_10"].radii.Large], [1, 3], "jewelRadii['3_15'] before 3.16");
  assert.equal(t.legionKeystones.karui_keystone_1, "Strength of Blood");
  assert.equal(t.legionKeystones.vaal_keystone_1, "Divine Flesh");
  assert.ok(t.keystoneMapNames.includes("Divine Flesh") && t.keystoneMapNames.includes("Chaos Inoculation"));
  assert.deepEqual(t.ringSlotNodes, ["43902"], "The Unseen Hand");
  assert.equal(Object.values(t.clusterSockets).filter((s) => s[0] === 2).length, 6, "six large sockets");
});
